/*
  Lingua Bud interface translations (see js/i18n.js for how they are applied).

  Keys are the exact English text shown in the app. Spanish is neutral
  (tú, no vosotros, no regional words) for Spain and Latin America;
  Portuguese is Brazilian (você). French is from France (vous, thin space
  before ? ! : ;). Arabic is Modern Standard Arabic (right to
  left; %1{one:…|few:…} picks the Arabic number form). Country and language names are the
  standard CLDR names, reviewed and corrected where the standard form reads
  oddly (e.g. "Costa de Marfil", not "Côte d'Ivoire").

  text:     exact text  -> translation ({slots} filled by lbI18n.f())
  mixed:    sentences containing a link/bold word: {0}…{/0} is that element
  patterns: text with numbers/names; $1 as is, $n1 translated name, $l1 lowercase name
  names:    country and language names (dropdowns, tags, cards)
*/
