      "Your free 15-minute trial is a no-obligation introduction. Use this time to meet your instructor, discuss your language goals, and see if their teaching style is the right fit for you. After your trial you can decide whether to book a full lesson.": "Sua aula experimental grátis de 15 minutos é uma apresentação sem compromisso. Aproveite para conhecer seu professor, conversar sobre seus objetivos com o idioma e ver se o estilo de ensino combina com você. Depois da aula experimental, você decide se quer agendar uma aula completa.",
      "Before booking a lesson, please set your timezone in your profile settings. Go to: Settings → My Timezone": "Antes de agendar uma aula, defina seu fuso horário nos ajustes do perfil. Vá em: Ajustes → Meu fuso horário",
