      "Your free 15-minute trial is a no-obligation introduction. Use this time to meet your instructor, discuss your language goals, and see if their teaching style is the right fit for you. After your trial you can decide whether to book a full lesson.": "Votre essai gratuit de 15 minutes est une première rencontre sans engagement. Profitez-en pour faire connaissance avec votre professeur, parler de vos objectifs et voir si sa méthode vous convient. Après l'essai, vous déciderez si vous voulez réserver un cours complet.",
