      "New@instructor": "جديد",
      "Your free 15-minute trial is a no-obligation introduction. Use this time to meet your instructor, discuss your language goals, and see if their teaching style is the right fit for you. After your trial you can decide whether to book a full lesson.": "تجربتك المجانية لمدة 15 دقيقة هي تعارف دون أي التزام. استغلّ هذا الوقت للتعرّف على معلمك ومناقشة أهدافك اللغوية ومعرفة ما إذا كان أسلوبه في التدريس يناسبك. بعد التجربة يمكنك أن تقرر ما إذا كنت ستحجز درسًا كاملًا.",
      "Before booking a lesson, please set your timezone in your profile settings. Go to: Settings → My Timezone": "قبل حجز درس، يُرجى ضبط منطقتك الزمنية في إعدادات ملفك الشخصي. انتقل إلى: الإعدادات ← منطقتي الزمنية",
      "Before booking a trial, please set your timezone in your profile settings. Go to: Settings → My Timezone": "قبل حجز تجربة، يُرجى ضبط منطقتك الزمنية في إعدادات ملفك الشخصي. انتقل إلى: الإعدادات ← منطقتي الزمنية",
